CREATE TABLE IF NOT EXISTS devices(id TEXT PRIMARY KEY,name TEXT NOT NULL,last_seen INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS routes(seq INTEGER PRIMARY KEY AUTOINCREMENT,message_id TEXT NOT NULL UNIQUE,device_id TEXT NOT NULL,thread_id TEXT NOT NULL,title TEXT NOT NULL,project TEXT NOT NULL,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS routes_device ON routes(device_id);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,device_id TEXT NOT NULL,thread_id TEXT NOT NULL,title TEXT NOT NULL,project TEXT NOT NULL,prompt TEXT NOT NULL,status TEXT NOT NULL,created INTEGER NOT NULL,lease_token TEXT,lease_until INTEGER);
CREATE INDEX IF NOT EXISTS jobs_pending ON jobs(device_id,status,created);
